#include "fstr/parts_model.hpp"
#include <fstream>
#include <iostream>
int main(int argc,char**argv){try{if(argc!=8)throw std::invalid_argument("runtime runtime-sha model width height input-rgba8 output-parts-f32");fstr::PartsModel model(argv[1],argv[2],argv[3]);fstr::AnalysisImage image;image.width=std::stoi(argv[4]);image.height=std::stoi(argv[5]);if(image.width<1||image.height<1||image.width>2048||image.height>2048)throw std::invalid_argument("Input size");image.rgba.resize(std::size_t(image.width)*std::size_t(image.height)*4);std::ifstream in(argv[6],std::ios::binary);in.read(reinterpret_cast<char*>(image.rgba.data()),static_cast<std::streamsize>(image.rgba.size()));if(!in||in.peek()!=EOF)throw std::runtime_error("Input size mismatch");const auto result=model.analyze(image);std::ofstream out(argv[7],std::ios::binary);out.write(reinterpret_cast<const char*>(result.probabilities.data()),static_cast<std::streamsize>(result.probabilities.size()*sizeof(result.probabilities[0])));if(!out)throw std::runtime_error("Output failed");std::cout<<result.width<<'x'<<result.height<<" native six-class inference complete\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
